# Manifest renderers shared by the scripts and hack/render-examples.sh.
# Each one prints YAML for the GPU type loaded with load_gpu (lib/common.sh).

# fake-gpu-operator Helm values: one node pool per type in GPU_TYPES. Pools use
# the gpuProduct/gpuCount/gpuMemory form so every type, H200 included, comes
# from gpus/*.env (fake-gpu-operator ships no H200 profile).
render_fgo_values() {
  local t
  cat <<EOF
# Generated by k8s-mock-test from gpus/*.env; do not edit.
topology:
  nodePoolLabelKey: run.ai/simulated-gpu-node-pool
  nodePools:
    default: null
EOF
  for t in $GPU_TYPES; do
    load_gpu "$t"
    cat <<EOF
    $GPU_TYPE:
      gpuProduct: $GPU_PRODUCT
      gpuCount: $GPU_COUNT
      gpuMemory: $GPU_MEMORY_MIB
EOF
  done
  cat <<EOF
# Gives KWOK nodes their nvidia.com/gpu capacity.
kwokGpuDevicePlugin:
  enabled: true
statusExporter:
  kwok:
    # Needs the Prometheus Operator CRDs; off so a bare cluster works.
    prometheusRule:
      enabled: false
# Leave RuntimeClass "nvidia" to a real GPU Operator if the cluster has one.
runtimeClass:
  enabled: false
EOF
}

# render_kwok_node <name>: a simulated node in the type's fake-gpu-operator
# pool. fake-gpu-operator adds nvidia.com/gpu and the nvidia.com/gpu.product,
# .count and .memory labels once the node exists.
render_kwok_node() {
  cat <<EOF
apiVersion: v1
kind: Node
metadata:
  name: $1
  annotations:
    node.alpha.kubernetes.io/ttl: "0"
    kwok.x-k8s.io/node: fake
  labels:
    type: kwok
    app.kubernetes.io/part-of: k8s-mock-test
    k8s-mock-test/gpu-type: $GPU_TYPE
    run.ai/simulated-gpu-node-pool: $GPU_TYPE
    kubernetes.io/arch: $NODE_ARCH
    kubernetes.io/hostname: $1
    kubernetes.io/os: linux
    kubernetes.io/role: agent
    node-role.kubernetes.io/agent: ""
    nvidia.com/gpu.family: $GPU_FAMILY
    nvidia.com/gpu.compute.major: "$GPU_COMPUTE_MAJOR"
    nvidia.com/gpu.compute.minor: "$GPU_COMPUTE_MINOR"
spec:
  taints:
    - key: kwok.x-k8s.io/node
      value: fake
      effect: NoSchedule
status:
  allocatable:
    cpu: "$NODE_CPU"
    memory: $NODE_MEMORY
    pods: "110"
  capacity:
    cpu: "$NODE_CPU"
    memory: $NODE_MEMORY
    pods: "110"
  nodeInfo:
    architecture: $NODE_ARCH
    kubeProxyVersion: fake
    kubeletVersion: fake
    operatingSystem: linux
  phase: Running
EOF
}

# render_gpu_pod <name> <namespace> <gpus>: a pod asking for <gpus> GPUs of the
# type, selected the way a real workload would (GPU Feature Discovery label).
render_gpu_pod() {
  cat <<EOF
apiVersion: v1
kind: Pod
metadata:
  name: $1
  namespace: $2
  labels:
    app.kubernetes.io/part-of: k8s-mock-test
    k8s-mock-test/gpu-type: $GPU_TYPE
spec:
  restartPolicy: Never
  nodeSelector:
    nvidia.com/gpu.product: $GPU_PRODUCT
  tolerations:
    # Only needed for KWOK nodes; harmless elsewhere.
    - key: kwok.x-k8s.io/node
      operator: Equal
      value: fake
      effect: NoSchedule
  containers:
    - name: cuda
      image: nvcr.io/nvidia/cuda:12.4.1-base-ubuntu22.04
      command: ["sleep", "infinity"]
      resources:
        limits:
          nvidia.com/gpu: $3
EOF
}
